package main

import (
	"errors"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"
)

func TestProbeNoRefresh(t *testing.T) {
	store := NewStore(30 * time.Second)
	now := time.Unix(1000, 0)
	store.now = func() time.Time { return now }
	store.Create("s1", "alice")

	// Repeated reads must NOT keep the session alive: three reads inside
	// the ttl window, then expiry lands exactly where the original
	// LastSeen put it (not where the last read put it).
	for i := 0; i < 3; i++ {
		now = time.Unix(int64(1000+10*(i+1)), 0)
		if _, err := store.Get("s1"); err != nil {
			t.Fatalf("read %d: %v", i, err)
		}
	}
	now = time.Unix(1031, 0)
	if _, err := store.Get("s1"); !errors.Is(err, ErrNotFound) {
		t.Fatalf("session survived polling past ttl: %v", err)
	}

	// Touch refreshes explicitly.
	store2 := NewStore(30 * time.Second)
	now2 := time.Unix(1000, 0)
	store2.now = func() time.Time { return now2 }
	store2.Create("s2", "bob")
	now2 = time.Unix(1020, 0)
	if err := store2.Touch("s2"); err != nil {
		t.Fatalf("touch: %v", err)
	}
	now2 = time.Unix(1045, 0)
	if _, err := store2.Get("s2"); err != nil {
		t.Fatalf("touched session expired early: %v", err)
	}
	if err := store2.Touch("missing"); !errors.Is(err, ErrNotFound) {
		t.Fatalf("touch unknown = %v, want ErrNotFound", err)
	}

	// Handler wiring: GET no longer refreshes (checked on store2), and
	// POST /session/touch refreshes (checked on a fresh store3 below).
	getHandler := sessionHandler(store2)
	now2 = time.Unix(1050, 0)
	rec := httptest.NewRecorder()
	getHandler(rec, httptest.NewRequest("GET", "/session?id=s2", nil))
	now2 = time.Unix(1085, 0)
	if _, err := store2.Get("s2"); !errors.Is(err, ErrNotFound) {
		t.Fatal("GET handler must not refresh")
	}
	// Fresh store for the touch handler: create at 1060, touch at 1080
	// (inside ttl), then verify Get survives past the ORIGINAL expiry.
	store3 := NewStore(30 * time.Second)
	now3 := time.Unix(1060, 0)
	store3.now = func() time.Time { return now3 }
	store3.Create("s3", "carol")
	touchHandlerFn := touchHandler(store3)
	now3 = time.Unix(1080, 0)
	rec = httptest.NewRecorder()
	touchHandlerFn(rec, httptest.NewRequest("POST", "/session/touch?id=s3", nil))
	if rec.Code != http.StatusNoContent {
		t.Fatalf("touch status = %d, want 204", rec.Code)
	}
	now3 = time.Unix(1095, 0)
	if _, err := store3.Get("s3"); err != nil {
		t.Fatalf("touch did not refresh: %v", err)
	}
	now3 = time.Unix(1120, 0)
	rec = httptest.NewRecorder()
	touchHandlerFn(rec, httptest.NewRequest("POST", "/session/touch?id=s3", nil))
	if rec.Code != http.StatusNotFound {
		t.Fatalf("touch expired status = %d, want 404", rec.Code)
	}
	if err := store2.Touch("missing"); !errors.Is(err, ErrNotFound) {
		t.Fatalf("touch unknown = %v, want ErrNotFound", err)
	}
}
EOF
go test -count=1 . ; rc=$? ; rm -f probe_norefresh_test.go ; exit $rc

